using System.Linq.Expressions; using AdDatabase.BLL.Entities; using AdDatabase.BLL.Models;
namespace AdDatabase.BLL.Interfaces;
public interface IGenericRepository<T> where T:class { Task<T?> GetByIdAsync(int id,CancellationToken ct=default); Task<List<T>> ListAsync(Expression<Func<T,bool>>? predicate=null,CancellationToken ct=default); Task<bool> ExistsAsync(Expression<Func<T,bool>> predicate,CancellationToken ct=default); Task AddAsync(T entity,CancellationToken ct=default); void Update(T entity); void Remove(T entity); Task<int> SaveChangesAsync(CancellationToken ct=default); }
public interface IAdRepository:IGenericRepository<Ad> { Task<PagedResult<Ad>> SearchAsync(AdFilter filter,CancellationToken ct=default); Task<Ad?> GetDetailsAsync(int id,CancellationToken ct=default); }
public interface IConversationRepository:IGenericRepository<Conversation> { Task<List<Conversation>> GetForUserAsync(int userId,CancellationToken ct=default); Task<Conversation?> GetWithMessagesAsync(int id,CancellationToken ct=default); }
public interface IUnitOfWork { IGenericRepository<User> Users {get;} IGenericRepository<Category> Categories {get;} IGenericRepository<Region> Regions {get;} IGenericRepository<Comment> Comments {get;} IGenericRepository<Notification> Notifications {get;} IGenericRepository<AdFavorite> Favorites {get;} IGenericRepository<Rating> Ratings {get;} IAdRepository Ads {get;} IConversationRepository Conversations {get;} IGenericRepository<Message> Messages {get;} Task<int> SaveChangesAsync(CancellationToken ct=default); }
